#!/usr/bin/env node
/**
 * Builds the website's Ndiédieng demo into site/ndiedieng, served at
 * kalangu.utachi.website/ndiedieng with no build step on the host:
 *
 *   site/api/ndiedieng/gemini.mjs     the Gemini function (src/geminiFunction.ts),
 *                                     which holds GEMINI_API_KEY on the host
 *   index.html, ui.js                 the dashboard (web/)
 *   assistant/index.html, assistant.js the assistant's page
 *   styles.css, assistant.css, common.js shared by both
 *   app/                              the prototype, compiled for the browser
 *   vendor/core, vendor/sim/phone.js  Kalangu, as built in this repository
 *
 *   pnpm build && node scripts/build-web.mjs           write it
 *   pnpm build && node scripts/build-web.mjs --check   fail if it is out of date
 *
 * The same page is served by server.ts, which talks to it over HTTP instead.
 */

import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from "node:fs";
import { mkdir, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, relative, resolve } from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const HERE = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const ROOT = resolve(HERE, "../..");
/** TypeScript's command-line entry, resolved from the repository's own install. */
const TSC = join(dirname(createRequire(join(ROOT, "package.json")).resolve("typescript/package.json")), "bin", "tsc");
const OUT = join(ROOT, "site", "ndiedieng");
/** The Gemini function, deployed next to the site (`/api/ndiedieng/gemini`). */
const API = join(ROOT, "site", "api", "ndiedieng");
/** Its entry: the key comes from the host's environment, never from the page. */
const ENTRY = `// Generated by examples/ndiedieng/scripts/build-web.mjs from src/geminiFunction.ts. Do not edit.
// The website's Gemini endpoint: set GEMINI_API_KEY in the host's settings (and optionally
// GEMINI_MODEL, GEMINI_SPEECH_MODEL, GEMINI_VOICE).
import { geminiHandler } from "./_lib/geminiFunction.mjs";

const handle = geminiHandler({
  apiKey: process.env.GEMINI_API_KEY,
  model: process.env.GEMINI_MODEL,
  speechModel: process.env.GEMINI_SPEECH_MODEL,
  voice: process.env.GEMINI_VOICE,
});
export const GET = handle;
export const POST = handle;
`;
/** The function's modules, as .mjs so they load as ES modules wherever the function's root is. */
const FUNCTION_MODULES = ["geminiFunction", "gemini", "schema"];

/** Every file under `dir`, as paths relative to it. */
function walk(dir, base = dir) {
  return readdirSync(dir).flatMap((name) => {
    const full = join(dir, name);
    return statSync(full).isDirectory() ? walk(full, base) : [relative(base, full)];
  });
}

export function build() {
  const files = new Map();
  const tmp = mkdtempSync(join(tmpdir(), "ndiedieng-web-"));
  try {
    // TypeScript's own entry, run with this Node: node_modules/.bin/tsc is a shell
    // script that Windows cannot execute directly.
    execFileSync(process.execPath, [TSC, "-p", "tsconfig.web.json", "--outDir", tmp], { cwd: HERE, stdio: "pipe" });
    for (const file of walk(tmp)) files.set(join("app", file), readFileSync(join(tmp, file), "utf8"));
  } catch (err) {
    throw new Error(`tsc failed:\n${err.stdout ?? ""}${err.stderr ?? ""}${err.stdout || err.stderr ? "" : err.message}`);
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }

  const core = join(ROOT, "packages", "core", "dist");
  if (!existsSync(join(core, "index.js"))) throw new Error("Build the packages first: pnpm build");
  for (const file of walk(core)) {
    // The command-line tool uses Node's file system; the browser never loads it.
    if (file.endsWith(".js") && file !== "cli.js") files.set(join("vendor", "core", file), readFileSync(join(core, file), "utf8"));
  }
  files.set(join("vendor", "sim", "phone.js"), readFileSync(join(ROOT, "packages", "sim", "dist", "phone.js"), "utf8"));

  // The function: its modules from the same compile, imports pointed at .mjs.
  const api = new Map([["gemini.mjs", ENTRY]]);
  for (const name of FUNCTION_MODULES) {
    const js = files.get(join("app", "src", `${name}.js`));
    if (!js) throw new Error(`${name}.js was not compiled`);
    api.set(join("_lib", `${name}.mjs`), js.replace(/from "\.\/([a-zA-Z]+)\.js"/g, 'from "./$1.mjs"').replace(/\n\/\/# sourceMappingURL=.*$/m, ""));
  }
  // The function is server code: the page never loads it.
  files.delete(join("app", "src", "geminiFunction.js"));

  for (const file of ["index.html", "styles.css", "common.js", "ui.js", "assistant/index.html", "assistant.css", "assistant.js"]) files.set(file, readFileSync(join(HERE, "web", file), "utf8"));
  // Source maps point at files outside the site; drop the comment.
  for (const [k, v] of files) if (k.endsWith(".js")) files.set(k, v.replace(/\n\/\/# sourceMappingURL=.*$/m, ""));
  return { files, api };
}

/** Writes `files` under `dir`, or lists what differs from them. */
function compare(dir, files, label) {
  const problems = [];
  for (const [file, content] of files) {
    const path = join(dir, file);
    if (!existsSync(path) || readFileSync(path, "utf8") !== content) problems.push(`out of date: ${label}/${file}`);
  }
  for (const f of existsSync(dir) ? walk(dir).filter((f) => !files.has(f)) : []) problems.push(`not built from source: ${label}/${f}`);
  return problems;
}
async function write(dir, files) {
  rmSync(dir, { recursive: true, force: true });
  for (const [file, content] of files) {
    await mkdir(dirname(join(dir, file)), { recursive: true });
    await writeFile(join(dir, file), content);
  }
}

async function main(argv) {
  const { files, api } = build();
  if (argv.includes("--check")) {
    const problems = [...compare(OUT, files, "site/ndiedieng"), ...compare(API, api, "site/api/ndiedieng")];
    for (const p of problems) console.error(p);
    if (problems.length) {
      console.error("Run: pnpm build && pnpm --filter @kalangu/example-ndiedieng build:web");
      return 1;
    }
    console.log(`The Ndiédieng demo is up to date (${files.size} files, and the Gemini function).`);
    return 0;
  }
  await write(OUT, files);
  await write(API, api);
  console.log(`Wrote ${files.size} files under site/ndiedieng, and the Gemini function under site/api/ndiedieng`);
  return 0;
}

main(process.argv.slice(2)).then(
  (code) => {
    process.exitCode = code;
  },
  (err) => {
    console.error(err.message ?? err);
    process.exitCode = 1;
  },
);
